export const SaveJobBody = zod.object({
  "jobId": zod.number()
})


/**
 * @summary Remove a saved job
 */
export const UnsaveJobParams = zod.object({
  "jobId": zod.coerce.number()
})


/**
 * @summary List all users (admin)
 */
export const ListUsersQueryParams = zod.object({
  "role": zod.enum(['job_seeker', 'recruiter', 'admin']).optional()
})

export const ListUsersResponseItem = zod.object({
  "id": zod.number(),
  "name": zod.string(),
  "email": zod.string(),
  "role": zod.enum(['job_seeker', 'recruiter', 'admin']),
  "createdAt": zod.coerce.date()
})
export const ListUsersResponse = zod.array(ListUsersResponseItem)


/**
 * @summary Delete user (admin)
 */
export const DeleteUserParams = zod.object({
  "id": zod.coerce.number()
})


/**
 * @summary List all jobs including pending (admin)
 */
export const ListAllJobsResponseItem = zod.object({
  "id": zod.number(),
  "companyId": zod.number().nullish(),
  "recruiterId": zod.number().optional(),
  "title": zod.string(),
  "description": zod.string(),
  "skills": zod.array(zod.string()).optional(),
  "location": zod.string(),
  "experienceMin": zod.number().nullish(),
  "experienceMax": zod.number().nullish(),
  "salaryMin": zod.number().nullish(),
  "salaryMax": zod.number().nullish(),
  "workMode": zod.enum(['remote', 'hybrid', 'onsite']),
  "employmentType": zod.enum(['full-time', 'part-time']),
  "status": zod.enum(['active', 'inactive', 'pending']),
  "postedAt": zod.coerce.date(),
  "company": zod.object({
  "id": zod.number(),
  "recruiterId": zod.number(),
  "name": zod.string(),
  "website": zod.string().nullish(),
  "description": zod.string().nullish(),
  "logo": zod.string().nullish(),
  "createdAt": zod.coerce.date()
}).optional()
})
export const ListAllJobsResponse = zod.array(ListAllJobsResponseItem)


